/* LEGO DNA — primary brick colors, chunky modular blocks, bold play energy */
.theme-lego-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.979 0 0);
  --surface-2: oklch(0.949 0 0);
  --fg: oklch(0.000 0 0);
  --fg-muted: oklch(0.471 0 0);
  --accent: oklch(0.543 0.216 28.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.523 0.142 248.5);
  --line: oklch(0.000 0 0);
  --success: oklch(0.537 0.162 146.4);
  --warning: oklch(0.871 0.178 91.8);
  --danger: oklch(0.543 0.216 28.3);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 3px 0 oklch(0 0 0 / 20%);
  --shadow-2: 0 6px 0 oklch(0 0 0 / 15%);
  --shadow-3: 0 12px 24px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 2px;
  --blur-amount: 0px;
  --font-display: "Nunito Sans", sans-serif;
  --font-body: "Nunito Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-lego-dna h1,
.theme-lego-dna h2,
.theme-lego-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-lego-dna { --font-ui: var(--font-display); }
.theme-lego-dna h1 { font-weight: 900; }
.theme-lego-dna button { border-bottom: 4px solid oklch(0 0 0 / 30%); font-weight: 800; }
.theme-lego-dna button:active { transform: translateY(2px); border-bottom-width: 2px; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
